<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { state, api, isAdmin, refreshUser, loadCatalog, notify } from '../lib/store.js'
import { asset, categories, priceLabel, personFields, roles, sizeLabel } from '../lib/catalog.js'
import ValidatedForm from '../components/ValidatedForm.vue'
import Field from '../components/Field.vue'
import Notices from '../components/Notices.vue'
import PasswordForm from '../components/PasswordForm.vue'
import OrdersList from '../components/OrdersList.vue'
import NotFound from './NotFound.vue'
const route = useRoute(), router = useRouter(), section = computed(() => route.params.section), titles = { produkte: 'Produkte', benutzer: 'Benutzer', bestellungen: 'Bestellungen', administratoren: 'Administratoren' }
const people = ref([]), orders = ref([]), admins = ref([]), loading = ref(true), busy = ref(false), error = ref(''), editing = ref(''), productForm = reactive({ name: '', description: '', price: 0, pricesBySize: {} }), adminForm = reactive({ firstName: '', lastName: '', email: '', password: '' }), creating = ref(false)
const mainAdmin = computed(() => state.user?.role === 'main_admin')
onMounted(async () => { if (!isAdmin()) return router.replace(state.user ? '/konto' : '/login'); try { if (['benutzer', 'bestellungen'].includes(section.value)) orders.value = (await api('/orders')).sort((a,b) => new Date(b.createdAt) - new Date(a.createdAt)); if (section.value === 'benutzer') people.value = (await api('/users')).filter(u => u.role === 'user'); if (section.value === 'administratoren') admins.value = sortAdmins(await api('/admins')) } catch (e) { error.value = e.message } finally { loading.value = false } })
function sortAdmins(list) { return [...list].sort((a,b) => a.role === 'main_admin' ? -1 : b.role === 'main_admin' ? 1 : new Date(a.createdAt || 0) - new Date(b.createdAt || 0)) }
function editProduct(product) { editing.value = product.id; error.value = ''; Object.assign(productForm, { name: product.name, description: product.description, price: product.price, pricesBySize: { ...product.pricesBySize } }) }
async function saveProduct(product) { busy.value = true; error.value = ''; try { await api(`/products/${product.id}`, { method: 'PUT', body: { name: productForm.name, description: productForm.description, ...(product.pricesBySize ? { pricesBySize: Object.fromEntries(Object.entries(productForm.pricesBySize).map(([size, value]) => [size, Number(value)])) } : { price: Number(productForm.price) }) } }); await loadCatalog(); editing.value = ''; notify('Das Produkt wurde gespeichert.') } catch (e) { error.value = e.message } finally { busy.value = false } }
function editAdmin(admin) { creating.value = false; editing.value = admin.id; error.value = ''; Object.assign(adminForm, { firstName: admin.firstName, lastName: admin.lastName, email: admin.email, password: '' }) }
function createAdmin() { editing.value = ''; creating.value = true; error.value = ''; Object.assign(adminForm, { firstName: '', lastName: '', email: '', password: '' }) }
async function saveAdmin() { busy.value = true; error.value = ''; try { const { password, ...personal } = adminForm; await api(creating.value ? '/admins' : `/admins/${editing.value}`, { method: creating.value ? 'POST' : 'PUT', body: creating.value ? { ...personal, password } : personal }); if (editing.value === state.user.id) await refreshUser(); admins.value = sortAdmins(await api('/admins')); editing.value = ''; creating.value = false; notify('Die Administratordaten wurden gespeichert.') } catch (e) { error.value = e.message } finally { busy.value = false } }
async function deleteAdmin(admin) { if (!window.confirm(`Administrator ${admin.firstName} ${admin.lastName} wirklich löschen?`)) return; busy.value = true; error.value = ''; try { await api(`/admins/${admin.id}`, { method: 'DELETE' }); admins.value = sortAdmins(await api('/admins')); if (editing.value === admin.id) editing.value = ''; notify('Der Administrator wurde gelöscht.') } catch (e) { error.value = e.message } finally { busy.value = false } }
function updateOrder(order) { orders.value = orders.value.map(o => o.id === order.id ? order : o) }
const userOrders = user => orders.value.filter(order => order.userId === user.id)
</script>
<template><NotFound v-if="!titles[section]" /><section v-else-if="isAdmin()" class="page admin-page"><div class="section-toolbar"><div><span class="eyebrow">VERWALTUNG</span><h1>{{ titles[section] }}</h1></div><button v-if="section === 'administratoren' && mainAdmin && !creating" class="button" @click="createAdmin">Administrator anlegen +</button></div><Notices :busy="loading" :error="error" />
  <div v-if="section === 'produkte'" class="admin-product-list"><article v-for="product in state.products" :key="product.id" class="admin-card"><div class="admin-product-heading"><img v-if="Object.values(product.imagesByColor)[0]?.[0]" :src="asset(Object.values(product.imagesByColor)[0][0])" :alt="product.name"><div><span class="eyebrow">{{ categories[product.category] }}</span><h2>{{ product.name }}</h2><p>{{ priceLabel(product) }}</p></div><button v-if="editing !== product.id" class="text-button" @click="editProduct(product)">Bearbeiten</button></div><ValidatedForm v-if="editing === product.id" class="admin-edit-form" @submit="saveProduct(product)"><Field v-model="productForm.name" label="Produktname" required /><Field v-model="productForm.description" label="Beschreibung" type="textarea" required /><div v-if="product.pricesBySize" class="form-grid"><Field v-for="size in product.sizes" :key="size" v-model="productForm.pricesBySize[size]" :label="`Preis ${sizeLabel(size)} (€)`" type="number" min="0" step="0.01" required /></div><Field v-else v-model="productForm.price" label="Preis (€)" type="number" min="0" step="0.01" required /><div class="row"><button class="button" :disabled="busy">Speichern</button><button type="button" class="text-button" @click="editing = ''">Abbrechen</button></div></ValidatedForm></article></div>
  <div v-else-if="section === 'benutzer'" class="admin-people-list"><p v-if="!loading && !people.length">Es sind noch keine Benutzer registriert.</p><article v-for="person in people" :key="person.id" class="admin-card"><div class="section-toolbar"><div><h2>{{ person.firstName }} {{ person.lastName }}</h2><a :href="`mailto:${person.email}`">{{ person.email }}</a></div><span class="status-badge">Benutzer</span></div><address v-if="Object.values(person.address || {}).some(Boolean)" class="admin-address">{{ person.address.street }}<br v-if="person.address.street">{{ person.address.postalCode }} {{ person.address.city }}<br v-if="person.address.postalCode || person.address.city">{{ person.address.country }}</address><h3>Bestellungen</h3><OrdersList v-if="userOrders(person).length" :orders="userOrders(person)" admin @update="updateOrder" /><p v-else class="muted">Für diesen Benutzer sind keine Bestellungen vorhanden.</p></article></div>
  <div v-else-if="section === 'bestellungen'"><OrdersList :orders="orders" admin @update="updateOrder" /><p v-if="!loading && !orders.length" class="empty-state">Es sind noch keine Bestellungen vorhanden.</p></div>
  <div v-else-if="section === 'administratoren'" class="admin-people-list"><article v-if="creating || editing" class="admin-card"><h2>{{ creating ? 'Neuen Administrator anlegen' : 'Administratordaten bearbeiten' }}</h2><ValidatedForm :key="creating ? 'new' : editing" @submit="saveAdmin"><div class="form-grid"><Field v-for="field in personFields.slice(0, 3)" :key="field.name" v-model="adminForm[field.name]" v-bind="field" required /><Field v-if="creating" v-model="adminForm.password" label="Passwort" type="password" autocomplete="new-password" required /></div><div class="row"><button class="button" :disabled="busy">{{ creating ? 'Administrator anlegen' : 'Speichern' }}</button><button type="button" class="text-button" @click="creating = false; editing = ''">Abbrechen</button></div></ValidatedForm></article><article v-for="admin in admins" :key="admin.id" class="admin-card"><div class="section-toolbar"><div><span class="eyebrow">{{ roles[admin.role] }}{{ admin.id === state.user.id ? ' · Dein Konto' : '' }}</span><h2>{{ admin.firstName }} {{ admin.lastName }}</h2><p>{{ admin.email }}</p></div><div class="row"><button v-if="mainAdmin || admin.id === state.user.id" class="text-button" @click="editAdmin(admin)">Bearbeiten</button><button v-if="mainAdmin && admin.id !== state.user.id" class="text-button danger" :disabled="busy" @click="deleteAdmin(admin)">Löschen</button></div></div><details v-if="admin.id === state.user.id" class="admin-password"><summary>Passwort ändern</summary><PasswordForm /></details></article></div>
</section></template>
